-- Generated by Gemini 3 Flash (AI)
-- This module computes a strictly unique unified order of elements from two lists.
-- It requires that the relative order of all elements is unambiguously defined.

local util = require "lib.util"

local function next_common_index(shared, list, index)
    while list[index] and not shared[list[index]] do
        index = index + 1
    end
    return index
end

local function compute_shared_order(list_1, list_2)
    -- 1. Setup shared element set for synchronization points
    local set_1 = util.list_to_set(list_1)
    local set_2 = util.list_to_set(list_2)
    local shared = util.set_intersection(set_1, set_2)

    local combined_order = {}
    local i1, i2 = 1, 1

    -- 2. Traverse both lists and merge them at shared anchor points
    while i1 <= #list_1 or i2 <= #list_2 do
        local anchor_i1 = next_common_index(shared, list_1, i1)
        local anchor_i2 = next_common_index(shared, list_2, i2)

        -- Ambiguity Check: If both lists contain unique elements in the current gap,
        -- their relative order to each other is undefined.
        local has_unique_1 = anchor_i1 > i1
        local has_unique_2 = anchor_i2 > i2

        if has_unique_1 and has_unique_2 then
            error(string.format(
                    "Ambiguous order: Elements starting with '%s' and '%s' have no defined relative sequence.",
                    tostring(list_1[i1]), tostring(list_2[i2])
            ))
        end

        -- Add unique elements from the list that contains them in this segment
        for k = i1, anchor_i1 - 1 do
            table.insert(combined_order, list_1[k])
        end
        for k = i2, anchor_i2 - 1 do
            table.insert(combined_order, list_2[k])
        end

        -- 3. Handle the synchronization (anchor) point
        local val1 = list_1[anchor_i1]
        local val2 = list_2[anchor_i2]

        if val1 and val2 then
            -- Both lists must agree on the next shared element
            if val1 ~= val2 then
                error(string.format(
                        "Order conflict: List 1 expects shared element '%s', but List 2 has '%s'.",
                        tostring(val1), tostring(val2)
                ))
            end
            table.insert(combined_order, val1)
            i1, i2 = anchor_i1 + 1, anchor_i2 + 1
        elseif val1 or val2 then
            -- One list has a shared element that the other does not (out of sync)
            error("Ambiguous order: A shared element appears out of sequence or is missing in one list.")
        else
            -- End of both lists reached
            break
        end
    end

    return combined_order
end

return compute_shared_order
